export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[*_`[\]()#]/g, '') // strip markdown syntax chars
    .replace(/[^\w\s-]/g, '')    // remove non-word chars
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim();
}

export interface Heading {
  level: 2 | 3;
  text: string;
  id: string;
}

export function extractHeadings(markdown: string): Heading[] {
  const headings: Heading[] = [];
  const regex = /^(#{2,3})\s+(.+)$/gm;
  let match;
  while ((match = regex.exec(markdown)) !== null) {
    const level = match[1].length as 2 | 3;
    const raw = match[2].trim();
    // Strip inline markdown so the text matches what childrenToText produces
    const text = raw
      .replace(/\*\*(.+?)\*\*/g, '$1')
      .replace(/\*(.+?)\*/g, '$1')
      .replace(/`(.+?)`/g, '$1')
      .replace(/\[(.+?)\]\(.+?\)/g, '$1');
    headings.push({ level, text, id: slugify(text) });
  }
  return headings;
}

export function childrenToText(children: React.ReactNode): string {
  // Imported lazily to avoid circular deps — used only in heading renderers
  const { Children, isValidElement } = require('react') as typeof import('react');
  return Children.toArray(children)
    .map((child) => {
      if (typeof child === 'string') return child;
      if (typeof child === 'number') return String(child);
      if (isValidElement(child)) return childrenToText((child.props as any).children ?? '');
      return '';
    })
    .join('');
}
