import React from 'react';
import styled from '@emotion/styled';
import { NavTree, theme } from '@atlantis/shared';
import type { NavEntry, NavigationConfig } from '@atlantis/shared';

const Nav = styled.nav`
  padding: ${theme.spacing.sm} 0;
`;

interface SidebarProps {
  config: NavigationConfig;
  activeId: string | null;
  onSelect: (entry: NavEntry) => void;
}

export function Sidebar({ config, activeId, onSelect }: SidebarProps) {
  return (
    <Nav>
      <NavTree entries={config.entries} activeId={activeId} onSelect={onSelect} />
    </Nav>
  );
}

export default Sidebar;
